Here's a complete, dependency-free Account Settings screen for React Native (TypeScript) — profile row, grouped settings rows with a toggle example, and a Delete Account action behind a native confirmation dialog.

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useMemo, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Image,
  Platform,
  Pressable,
  SafeAreaView,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  View,
} from 'react-native';

type Profile = {
  name: string;
  email: string;
  avatarUrl?: string;
};

type ToggleRow = {
  key: string;
  type: 'toggle';
  label: string;
  value: boolean;
  onToggle: (value: boolean) => void;
};

type NavigateRow = {
  key: string;
  type: 'navigate';
  label: string;
  onPress: () => void;
};

type SettingsRowData = ToggleRow | NavigateRow;

type Section = {
  key: string;
  title: string;
  rows: SettingsRowData[];
};

export type AccountSettingsScreenProps = {
  profile: Profile;
  onEditProfile: () => void;
  onNavigate?: (key: string) => void;
  onLogout?: () => void;
  /** Should reject on failure; the screen handles the loading state and error alert. */
  onDeleteAccount: () => Promise<void>;
};

const COLORS = {
  background: '#F2F2F7',
  card: '#FFFFFF',
  border: '#E3E3E8',
  textPrimary: '#1C1C1E',
  textSecondary: '#6B6B70',
  accent: '#007AFF',
  destructive: '#D70015',
};

function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '?';
  const first = parts[0]!.charAt(0);
  const last = parts.length > 1 ? parts[parts.length - 1]!.charAt(0) : '';
  return (first + last).toUpperCase();
}

function ProfileRow({ profile, onPress }: { profile: Profile; onPress: () => void }) {
  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`Edit profile for ${profile.name}`}
      android_ripple={{ color: COLORS.border }}
      style={({ pressed }) => [
        styles.profileRow,
        Platform.OS === 'ios' && pressed && { opacity: 0.6 },
      ]}
    >
      {profile.avatarUrl ? (
        <Image source={{ uri: profile.avatarUrl }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatar, styles.avatarFallback]}>
          <Text style={styles.avatarInitials}>{getInitials(profile.name)}</Text>
        </View>
      )}
      <View style={styles.profileText}>
        <Text style={styles.profileName} numberOfLines={1}>
          {profile.name}
        </Text>
        <Text style={styles.profileEmail} numberOfLines={1}>
          {profile.email}
        </Text>
      </View>
      <Text style={styles.chevron}>{'›'}</Text>
    </Pressable>
  );
}

function SettingsRow({ row, isLast }: { row: SettingsRowData; isLast: boolean }) {
  if (row.type === 'toggle') {
    return (
      <View
        style={[styles.row, isLast && styles.rowLast]}
        accessibilityRole="switch"
        accessibilityLabel={row.label}
      >
        <Text style={styles.rowLabel}>{row.label}</Text>
        <Switch value={row.value} onValueChange={row.onToggle} />
      </View>
    );
  }

  return (
    <Pressable
      onPress={row.onPress}
      accessibilityRole="button"
      accessibilityLabel={row.label}
      android_ripple={{ color: COLORS.border }}
      style={({ pressed }) => [
        styles.row,
        isLast && styles.rowLast,
        Platform.OS === 'ios' && pressed && { backgroundColor: COLORS.border },
      ]}
    >
      <Text style={styles.rowLabel}>{row.label}</Text>
      <Text style={styles.chevron}>{'›'}</Text>
    </Pressable>
  );
}

function SectionCard({ section }: { section: Section }) {
  return (
    <View style={styles.section}>
      <Text style={styles.sectionTitle}>{section.title}</Text>
      <View style={styles.card}>
        {section.rows.map((row, index) => (
          <SettingsRow key={row.key} row={row} isLast={index === section.rows.length - 1} />
        ))}
      </View>
    </View>
  );
}

export default function AccountSettingsScreen({
  profile,
  onEditProfile,
  onNavigate,
  onLogout,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);
  const [biometricEnabled, setBiometricEnabled] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const navigate = useCallback(
    (key: string) => {
      onNavigate?.(key);
    },
    [onNavigate]
  );

  const handleDeleteAccount = useCallback(() => {
    if (isDeleting) return;

    Alert.alert(
      'Delete account?',
      'This permanently deletes your account and all associated data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            setIsDeleting(true);
            try {
              await onDeleteAccount();
            } catch (error) {
              Alert.alert(
                'Something went wrong',
                error instanceof Error
                  ? error.message
                  : 'We could not delete your account. Please try again.'
              );
            } finally {
              setIsDeleting(false);
            }
          },
        },
      ],
      { cancelable: true }
    );
  }, [isDeleting, onDeleteAccount]);

  const sections: Section[] = useMemo(
    () => [
      {
        key: 'preferences',
        title: 'PREFERENCES',
        rows: [
          {
            key: 'notifications',
            type: 'toggle',
            label: 'Push notifications',
            value: notificationsEnabled,
            onToggle: setNotificationsEnabled,
          },
          {
            key: 'biometric',
            type: 'toggle',
            label: Platform.OS === 'ios' ? 'Face ID / Touch ID' : 'Biometric unlock',
            value: biometricEnabled,
            onToggle: setBiometricEnabled,
          },
        ],
      },
      {
        key: 'account',
        title: 'ACCOUNT',
        rows: [
          {
            key: 'password',
            type: 'navigate',
            label: 'Change password',
            onPress: () => navigate('password'),
          },
          {
            key: 'privacy',
            type: 'navigate',
            label: 'Privacy',
            onPress: () => navigate('privacy'),
          },
          {
            key: 'help',
            type: 'navigate',
            label: 'Help & support',
            onPress: () => navigate('help'),
          },
        ],
      },
    ],
    [notificationsEnabled, biometricEnabled, navigate]
  );

  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        contentInsetAdjustmentBehavior="automatic"
      >
        <View style={styles.card}>
          <ProfileRow profile={profile} onPress={onEditProfile} />
        </View>

        {sections.map((section) => (
          <SectionCard key={section.key} section={section} />
        ))}

        {onLogout && (
          <View style={styles.section}>
            <View style={styles.card}>
              <Pressable
                onPress={onLogout}
                accessibilityRole="button"
                accessibilityLabel="Log out"
                android_ripple={{ color: COLORS.border }}
                style={({ pressed }) => [
                  styles.row,
                  styles.rowLast,
                  Platform.OS === 'ios' && pressed && { backgroundColor: COLORS.border },
                ]}
              >
                <Text style={[styles.rowLabel, { color: COLORS.accent }]}>Log out</Text>
              </Pressable>
            </View>
          </View>
        )}

        <View style={styles.section}>
          <View style={styles.card}>
            <Pressable
              onPress={handleDeleteAccount}
              disabled={isDeleting}
              accessibilityRole="button"
              accessibilityLabel="Delete account"
              accessibilityState={{ disabled: isDeleting, busy: isDeleting }}
              android_ripple={{ color: COLORS.border }}
              style={({ pressed }) => [
                styles.row,
                styles.rowLast,
                styles.deleteRow,
                Platform.OS === 'ios' && pressed && { backgroundColor: COLORS.border },
              ]}
            >
              {isDeleting ? (
                <ActivityIndicator color={COLORS.destructive} />
              ) : (
                <Text style={styles.deleteLabel}>Delete account</Text>
              )}
            </Pressable>
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const ROW_MIN_HEIGHT = 48;

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: COLORS.background,
  },
  scrollContent: {
    paddingVertical: 16,
    paddingBottom: 40,
  },
  section: {
    marginTop: 20,
    paddingHorizontal: 16,
  },
  sectionTitle: {
    fontSize: 13,
    fontWeight: '600',
    color: COLORS.textSecondary,
    marginBottom: 6,
    marginLeft: 4,
  },
  card: {
    backgroundColor: COLORS.card,
    borderRadius: 12,
    marginHorizontal: 16,
    overflow: 'hidden',
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: 16,
    minHeight: 72,
  },
  avatar: {
    width: 52,
    height: 52,
    borderRadius: 26,
  },
  avatarFallback: {
    backgroundColor: COLORS.accent,
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitials: {
    color: '#FFFFFF',
    fontSize: 18,
    fontWeight: '600',
  },
  profileText: {
    flex: 1,
    marginLeft: 14,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
    color: COLORS.textPrimary,
  },
  profileEmail: {
    fontSize: 14,
    color: COLORS.textSecondary,
    marginTop: 2,
  },
  chevron: {
    fontSize: 20,
    color: COLORS.textSecondary,
    marginLeft: 8,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    minHeight: ROW_MIN_HEIGHT,
    paddingHorizontal: 16,
    borderBottomWidth: 1,
    borderBottomColor: COLORS.border,
  },
  rowLast: {
    borderBottomWidth: 0,
  },
  rowLabel: {
    fontSize: 16,
    color: COLORS.textPrimary,
  },
  deleteRow: {
    justifyContent: 'center',
  },
  deleteLabel: {
    fontSize: 16,
    fontWeight: '600',
    color: COLORS.destructive,
  },
});
```

